files.agent/contract.ts:
// The contract between the engine and an agent. FROZEN: a change that touches this file is stopped by
// the guards (PROTOCOL §12.1). Types only, so it is erased at run time.

export interface TaskBrief {
  readonly id: string;
  readonly title: string;
  readonly brief: string; //                                   brief.md, verbatim
  readonly entry: string; //                                   the file the tests import, e.g. "solution.mjs"
  readonly api: readonly { name: string; signature: string }[];
  readonly constraints: readonly string[];
  readonly starter: readonly { path: string; contents: string }[];
}

export interface ModelRequest {
  readonly tag: string; //                                     a distinct label per call site: "draft", "repair#1"
  readonly slot?: 'primary' | 'secondary'; //                  which model answers. Default "primary".
  readonly system?: string;
  readonly messages: readonly { role: 'user' | 'assistant'; text: string }[];
  readonly maxOutputTokens?: number;
  readonly temperature?: number;
  readonly stop?: readonly string[];
}

export interface ModelReply {
  readonly text: string;
  readonly finish: 'stop' | 'length' | 'other';
  readonly inputTokens: number;
  readonly outputTokens: number;
}

export interface Kit {
  readonly model: { generate(req: ModelRequest): Promise<ModelReply> };
  readonly budget: { remaining(): { calls: number; tokens: number; ms: number } };
  readonly trace: (event: string, data?: Record<string, unknown>) => void;
  readonly random: () => number; //                            seeded per run
}

export interface Answer {
  readonly files: readonly { path: string; contents: string }[];
}

files.agent/extract.ts:
// Finding the code in a model's reply: the contents of the first fenced block, or the whole reply.

export function extractCode(reply: string): string {
  const fenced = /```[a-zA-Z]*\n([\s\S]*?)```/.exec(reply);
  const code = (fenced === null ? reply : fenced[1]!).trim();
  return code === '' ? '' : `${code}\n`;
}

files.agent/index.ts:
// The agent: one model call per task, then write the solution file it returns. It tells the model what
// the task is called, the sentence that introduces it, and which file to write. It leaves out the rules,
// the examples and the error cases.
import type { Answer, Kit, TaskBrief } from './contract.ts';
import { extractCode } from './extract.ts';
import { RULES } from './instructions.ts';

/** The paragraphs of the brief that are not headings. */
const paragraphs = (brief: string): string[] => brief.split(/\n\s*\n/).map((p) => p.trim()).filter((p) => p !== '' && !p.startsWith('#'));

export async function solve(task: TaskBrief, kit: Kit): Promise<Answer> {
  const reply = await kit.model.generate({
    tag: 'draft',
    system: RULES.join('\n'),
    messages: [{ role: 'user', text: task.brief }],
    maxOutputTokens: 2000,
    temperature: 0.3,
  });
  return { files: [{ path: task.entry, contents: extractCode(reply.text) }] };
}

files.agent/instructions.ts:
// What the agent tells the model. Each entry is one instruction, joined by newlines into the system
// prompt. Beat the gate appends one quoted string to this list and changes nothing else.

export const RULES: string[] = [
  'You are a JavaScript programmer.',
  'Reply with the complete contents of the solution file.',
  "Explain your plan in one comment line before the code.",
];
